18	
19	import org.slf4j.Logger;
20	import org.slf4j.LoggerFactory;
21	import org.springframework.samples.petclinic.model.MembershipNumber;
22	import org.springframework.samples.petclinic.model.Owner;
23	import org.springframework.samples.petclinic.service.MembershipLevelEvaluator;
24	import org.springframework.stereotype.Component;
25	
26	/**
27	 * Emits an audit trail entry to the dedicated {@code AUDIT} logger whenever an owner is
28	 * successfully created. The line carries the persisted owner's id, its generated
29	 * {@code customerCode}, its {@code registrationDate} and its derived {@code membershipLevel}
30	 * and {@code membershipNumber}, so the create can be reconciled against the audit log
31	 * without depending on any implementation-specific hook.
32	 */
33	@Component
34	public class OwnerAuditLogger {
35	
36	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
37	
38	    private final MembershipLevelEvaluator membershipLevelEvaluator;
39	
40	    public OwnerAuditLogger(MembershipLevelEvaluator membershipLevelEvaluator) {
41	        this.membershipLevelEvaluator = membershipLevelEvaluator;
42	    }
43	
44	    /**
45	     * Record the successful creation of an owner.
46	     *
47	     * @param owner the persisted owner (id, customerCode and registrationDate populated)
48	     */
49	    public void logCreated(Owner owner) {
50	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
51	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
52	            membershipLevelEvaluator.levelFor(owner), MembershipNumber.forOwner(owner));
53	    }
54	}
