18	
19	import org.springframework.beans.factory.annotation.Autowired;
20	import org.springframework.samples.petclinic.model.Owner;
21	import org.springframework.stereotype.Component;
22	
23	import java.time.Clock;
24	import java.time.LocalDate;
25	import java.util.OptionalInt;
26	
27	/**
28	 * Scores an owner's membership and maps that score to a numeric level. Points start at 0
29	 * and accrue for each qualifying attribute:
30	 * <ul>
31	 *   <li>+{@value #EMAIL_POINTS} when the owner has an email address on file;</li>
32	 *   <li>+{@value #NO_NAMESAKE_POINTS} when the owner has no namesakes ({@code namesakeCount} is 0);</li>
33	 *   <li>+{@value #LARGE_HOUSEHOLD_POINTS} when the owner's household has {@value #LARGE_HOUSEHOLD_SIZE}
34	 *       or more members;</li>
35	 *   <li>+{@value #TENURE_POINTS} when the owner's tenure exceeds {@value #TENURE_THRESHOLD_FISCAL_YEARS}
36	 *       fiscal year(s).</li>
37	 * </ul>
38	 * The point total maps to a level as 1 (0-1 points), 2 (2-3), 3 (4-5) and 4 (6 or more).
39	 */
40	@Component
41	public class MembershipLevelEvaluator {
42	
43	    /** Points gained when an email address is on file. */
44	    static final int EMAIL_POINTS = 2;
45	
46	    /** Points gained when the owner has no namesakes. */
47	    static final int NO_NAMESAKE_POINTS = 1;
48	
49	    /** Points gained when the owner belongs to a large household. */
50	    static final int LARGE_HOUSEHOLD_POINTS = 2;
51	
52	    /** Points gained when tenure exceeds {@value #TENURE_THRESHOLD_FISCAL_YEARS} fiscal year(s). */
53	    static final int TENURE_POINTS = 3;
54	
55	    /** Household size at or above which {@link #LARGE_HOUSEHOLD_POINTS} apply. */
56	    static final int LARGE_HOUSEHOLD_SIZE = 3;
57	
58	    /** Tenure, in whole fiscal years, that must be exceeded for the tenure points to apply. */
59	    static final long TENURE_THRESHOLD_FISCAL_YEARS = 1;
60	
61	    private final ClinicService clinicService;
62	
63	    private final Clock clock;
64	
65	    @Autowired
66	    public MembershipLevelEvaluator(ClinicService clinicService) {
67	        this(clinicService, Clock.systemDefaultZone());
68	    }
69	
70	    MembershipLevelEvaluator(ClinicService clinicService, Clock clock) {
71	        this.clinicService = clinicService;
72	        this.clock = clock;
73	    }
74	
75	    /**
76	     * @param owner the owner whose membership points are evaluated
77	     * @return the owner's membership points, or {@code null} when the owner is not known
78	     */
79	    public Integer pointsFor(Owner owner) {
80	        if (owner == null) {
81	            return null;
82	        }
83	        int points = 0;
84	        if (owner.hasEmail()) {
85	            points += EMAIL_POINTS;
86	        }
87	        if (hasNoNamesakes(owner)) {
88	            points += NO_NAMESAKE_POINTS;
89	        }
90	        if (hasLargeHousehold(owner)) {
91	            points += LARGE_HOUSEHOLD_POINTS;
92	        }
93	        if (hasQualifyingTenure(owner)) {
94	            points += TENURE_POINTS;
95	        }
96	        return points;
97	    }
98	
99	    /**
100	     * @param owner the owner whose level is evaluated
101	     * @return the owner's membership level capped at one above the highest level among the
102	     *     owner's existing household members, or {@code null} when the owner is not known
103	     */
104	    public Integer levelFor(Owner owner) {
105	        Integer points = pointsFor(owner);
106	        return points == null ? null : capToHousehold(owner, levelForPoints(points));
107	    }
108	
109	    /**
110	     * Caps {@code level} at one above the highest level among the owner's existing household
111	     * members. Member levels are evaluated uncapped to avoid recursion; the owner itself and
112	     * soft-deleted owners are excluded. With no household members no cap applies.
113	     */
114	    private int capToHousehold(Owner owner, int level) {
115	        if (owner.getHouseholdId() == null) {
116	            return level;
117	        }
118	        OptionalInt maxMemberLevel = clinicService.findOwnersInHousehold(owner.getHouseholdId()).stream()
119	            .filter(member -> !member.isDeleted())
120	            .filter(member -> !isSameOwner(member, owner))
121	            .mapToInt(member -> levelForPoints(pointsFor(member)))
122	            .max();
123	        return maxMemberLevel.isPresent() ? Math.min(level, maxMemberLevel.getAsInt() + 1) : level;
124	    }
125	
126	    private boolean isSameOwner(Owner member, Owner owner) {
127	        return owner.getId() != null && owner.getId().equals(member.getId());
128	    }
129	
130	    /**
131	     * Maps a point total to a membership level: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6 or more).
132	     */
133	    private int levelForPoints(int points) {
134	        if (points <= 1) {
135	            return 1;
136	        }
137	        if (points <= 3) {
138	            return 2;
139	        }
140	        if (points <= 5) {
141	            return 3;
142	        }
143	        return 4;
144	    }
145	
146	    private boolean hasNoNamesakes(Owner owner) {
147	        return owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
148	    }
149	
150	    private boolean hasLargeHousehold(Owner owner) {
151	        return owner.getHouseholdId() != null
152	            && clinicService.countOwnersInHousehold(owner.getHouseholdId()) >= LARGE_HOUSEHOLD_SIZE;
153	    }
154	
155	    private boolean hasQualifyingTenure(Owner owner) {
156	        return owner.tenureInFiscalYears(LocalDate.now(clock)) > TENURE_THRESHOLD_FISCAL_YEARS;
157	    }
158	}
